"""Declarations and change records for state-owned data."""

from copy import deepcopy
from dataclasses import dataclass
from typing import Any

from .exceptions import InvalidDefinition


_MISSING = object()


class DataVar:
    """A state variable with an optional type and per-entry factory."""

    def __init__(self, default=_MISSING, *, factory=None, type=None):
        if default is not _MISSING and factory is not None:
            raise InvalidDefinition("DataVar cannot specify both default and factory")
        self.default = default
        self.factory = factory
        self.type = type

    def create(self):
        value = self.factory() if self.factory is not None else (
            None if self.default is _MISSING else deepcopy(self.default)
        )
        self.validate(value)
        return value

    def validate(self, value):
        if self.type is not None and not isinstance(value, self.type):
            raise InvalidDefinition(f"Expected data value of type {self.type!r}")


@dataclass(frozen=True)
class DataChangeInfo:
    state_id: str
    key: str
    old_value: Any
    new_value: Any

    _callbacks: Any = None,
    data: Any = None,
):
    if data is not None and (not isinstance(data, dict) or any(not isinstance(k, str) for k in data)):
        raise InvalidDefinition("State data must be a dict with string keys")
    self.data = dict(data) if data is not None else {}
    self.name = name

self._state_data: Dict[str, dict] = {}
self._history_data: Dict[str, dict] = {}
self._data_changes: List[DataChangeInfo] = []
self.model: TModel = model if model is not None else Model()  # type: ignore[assignment]

def get_state_data(self, state):
    """Return the active state's own data, or None if it is inactive."""
    return self._state_data.get(state if isinstance(state, str) else state.id)

@property
def state_data_values(self):
    return deepcopy(self._state_data)

def set_state_data(self, state, key, value):
    state_id = state if isinstance(state, str) else state.id
    data = self._state_data.get(state_id)
    declaration = next((s for s in self.states_map.values() if s.id == state_id), None)
    if data is None or declaration is None or key not in declaration.data:
        raise InvalidDefinition(f"Inactive state or undeclared data key: {state_id}.{key}")
    spec = declaration.data[key]
    if isinstance(spec, DataVar):
        spec.validate(value)
    old = deepcopy(data[key])
    data[key] = value
    self._data_changes.append(DataChangeInfo(state_id, key, old, deepcopy(value)))

def get_data_changes(self):
    return list(self._data_changes)

def _enter_state_data(self, state, restored=None):
    if restored is not None:
        self._state_data[state.id] = deepcopy(restored)
        return
    self._state_data[state.id] = {
        key: spec.create() if isinstance(spec, DataVar) else spec() if callable(spec)
        else deepcopy(spec) for key, spec in state.data.items()
    }

def _state_data_scope(self, state):
    scope = {}
    for ancestor in reversed(list(state.ancestors())):
        scope.update(self._state_data.get(ancestor.id, {}))
    scope.update(self._state_data.get(state.id, {}))
    return scope

